package com.yuyutian.mytools.dshconnector.service;import com.yuyutian.mytools.dshconnector.model.DshModels.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import java.time.Instant;import java.util.List;import static org.assertj.core.api.Assertions.*;
/** DSH 会话服务测试。 */ @SpringBootTest class DshSessionServiceTest {@Autowired private DshSessionService service;
 @Test void shouldMigrateReplayAdvanceArchiveAndReconcile(){LegacyBinding binding=item("ACTIVE",3);var dry=service.migrate(new MigrationBatch("dsh-v1",true,List.of(binding)));var apply=service.migrate(new MigrationBatch("dsh-v1",false,List.of(binding)));var replay=service.migrate(new MigrationBatch("dsh-v1",false,List.of(binding)));assertThat(dry.accepted()).isEqualTo(1);assertThat(apply.accepted()).isEqualTo(1);assertThat(apply.digestSha256()).isEqualTo("5cb3268de098d6b54cee77053a086628a651549d9e2fa4e854f82a3ba3c1c842");assertThat(replay.skipped()).isEqualTo(1);assertThat(service.list(7)).singleElement().satisfies(value->assertThat(value.lastSequence()).isEqualTo(3));service.advance(7,"session-1",8);service.advance(7,"session-1",4);assertThat(service.list(7).getFirst().lastSequence()).isEqualTo(8);Reconciliation reconciliation=service.reconcile("dsh-v1");assertThat(reconciliation.migrationKey()).isEqualTo("dsh-v1");assertThat(reconciliation.itemCount()).isEqualTo(1);assertThat(reconciliation.collectionSha256()).isEqualTo(apply.digestSha256());service.archive(7,"session-1");assertThat(service.list(7)).isEmpty();}
 @Test void shouldRejectChangedIdentityPayload(){service.migrate(new MigrationBatch("dsh-v2",false,List.of(item("ACTIVE",1))));assertThat(service.migrate(new MigrationBatch("dsh-v2",false,List.of(item("ARCHIVED",1)))).rejected()).isEqualTo(1);}
 private LegacyBinding item(String status,long sequence){return new LegacyBinding(1,7,"session-1","default",status,sequence,Instant.EPOCH,Instant.EPOCH);}}
